using System.Text.Json;
using Clary.Api.Identity;
using Npgsql;
using NpgsqlTypes;
namespace Clary.Api;
public sealed partial class TicketRepository(NpgsqlDataSource db) {
 internal static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 internal static NpgsqlCommand Q(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,string sql){var q=new NpgsqlCommand(sql,conn,tx);q.Parameters.AddWithValue("company",c.CompanyId);q.Parameters.AddWithValue("user",c.UserId);return q;}
 internal static void P(NpgsqlCommand q,string name,object? value,NpgsqlDbType type)=>q.Parameters.AddWithValue(name,type,value??DBNull.Value);
 internal static string Text(string? value,int max,bool required=false){value=value?.Trim()??"";if((required&&value.Length==0)||value.Length>max)throw new ArgumentException($"Text must be {(required?"1":"0")} to {max} characters.");return value;}
 internal const string Visible="(@manager OR t.assignment_mode='All' OR EXISTS(SELECT 1 FROM ticket_assignees x WHERE x.company_id=t.company_id AND x.ticket_id=t.id AND x.user_id=@user))";
 const string Projection="""
 SELECT jsonb_build_object('priority',t.priority,'isWorkspaceSetup',t.is_workspace_setup,'id',t.id,'requestId',t.request_id,'title',t.title,'description',t.description,'type',t.type,
 'status',CASE t.state WHEN 'Ready' THEN 'Assigned' WHEN 'Completed' THEN 'Complete' WHEN 'Cancelled' THEN 'Canceled' ELSE t.state END,
 'revision',t.revision,'dueDate',t.due_date,'createdAt',t.created_at,'creatorUserId',t.creator_user_id,'creatorName',t.creator_name,'approverUserId',t.approver_user_id,'approverName',t.approver_name,'approvedAt',t.approved_at,
 'recipientEmployeeId',t.recipient_employee_id,'recipientName',e.display_name,'departmentId',t.department_id,'departmentName',d.name,'locationId',t.location_id,'locationName',l.name,'assignmentMode',t.assignment_mode,
 'assignees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',u.id,'displayName',u.display_name) ORDER BY u.display_name) FROM ticket_assignees x JOIN users u ON u.id=x.user_id WHERE x.company_id=t.company_id AND x.ticket_id=t.id),'[]'::jsonb),
 'assets',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'name',CASE WHEN @inventory OR a.employee_id=@employee THEN a.computer ELSE 'Restricted asset' END,'assetTag',CASE WHEN @inventory OR a.employee_id=@employee THEN a.asset_tag ELSE '' END,'assetType',CASE WHEN @inventory OR a.employee_id=@employee THEN a.category ELSE '' END,'brand',CASE WHEN @inventory OR a.employee_id=@employee THEN (SELECT a.custom_fields->>f.id::text FROM asset_fields f WHERE f.company_id=a.company_id AND lower(btrim(f.name)) IN ('brand','manufacturer') AND (f.asset_type_id IS NULL OR f.asset_type_id=a.asset_type_id) ORDER BY f.asset_type_id NULLS LAST LIMIT 1) END,'model',CASE WHEN @inventory OR a.employee_id=@employee THEN (SELECT a.custom_fields->>f.id::text FROM asset_fields f WHERE f.company_id=a.company_id AND lower(btrim(f.name))='model' AND (f.asset_type_id IS NULL OR f.asset_type_id=a.asset_type_id) ORDER BY f.asset_type_id NULLS LAST LIMIT 1) END,'status',CASE WHEN @inventory OR a.employee_id=@employee THEN a.status ELSE '' END,'outcome',x.outcome,'available',coalesce(@inventory OR a.employee_id=@employee,false)) ORDER BY a.asset_tag) FROM ticket_asset_links x JOIN inventory_assets a ON a.company_id=x.company_id AND a.id=x.asset_id WHERE x.company_id=t.company_id AND x.ticket_id=t.id),'[]'::jsonb),
 'documents',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.document_id,'title',CASE WHEN @inventory THEN x.document_title ELSE 'Restricted document' END,'available',@inventory AND x.document_id IS NOT NULL)) FROM ticket_document_links x WHERE x.company_id=t.company_id AND x.ticket_id=t.id),'[]'::jsonb),
 'checklist',t.checklist,'lines',coalesce(r.lines,t.fulfillment_lines,'[]'::jsonb))::text
 FROM equipment_tickets t LEFT JOIN employees e ON e.company_id=t.company_id AND e.id=t.recipient_employee_id LEFT JOIN inventory_departments d ON d.company_id=t.company_id AND d.id=t.department_id LEFT JOIN locations l ON l.company_id=t.company_id AND l.id=t.location_id LEFT JOIN equipment_requests r ON r.company_id=t.company_id AND r.id=t.request_id
 """;
 internal async Task<TicketDto?> Get(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,Guid id,CancellationToken ct){await using var q=Q(conn,tx,c,Projection+" WHERE t.company_id=@company AND NOT t.dismissed AND t.id=@id AND "+Visible);q.Parameters.AddWithValue("manager",TicketAccess.Manager(c));q.Parameters.AddWithValue("inventory",AccountPermissions.Allows(c,CompanyCapability.Read));P(q,"employee",c.EmployeeId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("id",id);var raw=await q.ExecuteScalarAsync(ct) as string;if(raw is null)return null;var t=JsonSerializer.Deserialize<TicketDto>(raw,Json)!;return t with{AllowedActions=TicketAccess.Actions(t,c)};}
 public async Task<TicketDto?> GetAsync(CompanyContext c,Guid id,CancellationToken ct){await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);return await Get(conn,tx,c,id,ct);}
 record Cursor(Guid Company,DateTime CreatedAt,Guid Id);
 public async Task<TicketPage<TicketDto>> ListAsync(CompanyContext c,TicketQuery filter,CancellationToken ct){
  if(filter.Limit is <1 or >100)throw new ArgumentException("Limit must be 1 to 100.");Cursor? cursor=null;if(filter.Cursor is {} raw){try{cursor=JsonSerializer.Deserialize<Cursor>(Convert.FromBase64String(raw),Json);}catch(Exception ex)when(ex is FormatException or JsonException){throw new ArgumentException("Invalid cursor.");}if(cursor?.Company!=c.CompanyId)throw new ArgumentException("Invalid cursor.");}
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);
  await using var q=Q(conn,tx,c,"SELECT t.id,t.created_at FROM equipment_tickets t WHERE t.company_id=@company AND NOT t.dismissed AND "+Visible+" AND (@search='' OR strpos(lower(t.title||' '||coalesce(t.description,'')),lower(@search))>0) AND (@status IS NULL OR CASE t.state WHEN 'Ready' THEN 'Assigned' WHEN 'Completed' THEN 'Complete' WHEN 'Cancelled' THEN 'Canceled' ELSE t.state END=@status) AND (@type IS NULL OR t.type=@type) AND (@priority IS NULL OR t.priority=@priority) AND (@recipient IS NULL OR t.recipient_employee_id=@recipient) AND (@location IS NULL OR t.location_id=@location) AND (@assignee IS NULL OR t.assignment_mode='All' OR EXISTS(SELECT 1 FROM ticket_assignees x WHERE x.company_id=t.company_id AND x.ticket_id=t.id AND x.user_id=@assignee)) AND (@asset IS NULL OR EXISTS(SELECT 1 FROM ticket_asset_links x WHERE x.company_id=t.company_id AND x.ticket_id=t.id AND x.asset_id=@asset)) AND (NOT @overdue OR (t.due_date<@today AND t.state NOT IN ('Complete','Canceled','Completed','Cancelled'))) AND (@after IS NULL OR (t.created_at,t.id)<(@after,@afterId)) ORDER BY t.created_at DESC,t.id DESC LIMIT @limit");
  q.Parameters.AddWithValue("manager",TicketAccess.Manager(c));q.Parameters.AddWithValue("search",Text(filter.Search,200));P(q,"status",string.IsNullOrWhiteSpace(filter.Status)?null:filter.Status,NpgsqlDbType.Text);P(q,"type",string.IsNullOrWhiteSpace(filter.Type)?null:filter.Type,NpgsqlDbType.Text);P(q,"priority",string.IsNullOrWhiteSpace(filter.Priority)?null:filter.Priority,NpgsqlDbType.Text);P(q,"recipient",filter.RecipientId,NpgsqlDbType.Uuid);P(q,"location",filter.LocationId,NpgsqlDbType.Uuid);P(q,"assignee",filter.AssigneeId,NpgsqlDbType.Uuid);P(q,"asset",filter.AssetId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("overdue",filter.Overdue);q.Parameters.AddWithValue("today",filter.Today??DateOnly.FromDateTime(DateTime.UtcNow));P(q,"after",cursor?.CreatedAt,NpgsqlDbType.TimestampTz);q.Parameters.AddWithValue("afterId",cursor?.Id??Guid.Empty);q.Parameters.AddWithValue("limit",filter.Limit+1);
  var ids=new List<(Guid Id,DateTime At)>();await using(var r=await q.ExecuteReaderAsync(ct))while(await r.ReadAsync(ct))ids.Add((r.GetGuid(0),r.GetDateTime(1)));
  var more=ids.Count>filter.Limit;if(more)ids.RemoveAt(ids.Count-1);var rows=new List<TicketDto>();foreach(var item in ids)if(await Get(conn,tx,c,item.Id,ct) is {} t)rows.Add(t);return new(rows,more?Convert.ToBase64String(JsonSerializer.SerializeToUtf8Bytes(new Cursor(c.CompanyId,ids[^1].At,ids[^1].Id),Json)):null);
 }
 internal static async Task<string> Actor(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,CancellationToken ct){await using var q=Q(conn,tx,c,"SELECT display_name FROM users WHERE id=@user");return (string)(await q.ExecuteScalarAsync(ct))!;}
 internal static async Task Activity(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,Guid id,string action,string? detail,CancellationToken ct){await using var q=Q(conn,tx,c,"INSERT INTO ticket_activity(company_id,ticket_id,id,actor_user_id,actor_name,action,detail) VALUES(@company,@ticket,@id,@user,@actor,@action,@detail)");q.Parameters.AddWithValue("ticket",id);q.Parameters.AddWithValue("id",Guid.NewGuid());q.Parameters.AddWithValue("actor",await Actor(conn,tx,c,ct));q.Parameters.AddWithValue("action",action);P(q,"detail",detail,NpgsqlDbType.Text);await q.ExecuteNonQueryAsync(ct);}
 public async Task<IReadOnlyList<TicketUser>> AssigneesAsync(CompanyContext c,CancellationToken ct){await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);if(!TicketAccess.Manager(c))return [new(c.UserId,await Actor(conn,tx,c,ct))];await using var q=Q(conn,tx,c,"SELECT u.id,u.display_name FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.company_id=@company AND m.active AND u.active ORDER BY u.display_name,u.id");var users=new List<TicketUser>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))users.Add(new(r.GetGuid(0),r.GetString(1)));return users;}
}
